test('tidy-prs: merged PRs on the signal never enter the sweep', () => {
  const merged = { merged: [{ number: 42, title: 'landed last night' }] };
  assert.equal(tidyPrs.precondition(S({ prs: { open: [], touched: [], ...merged } })).run, false);
